<?php
require_once __DIR__ . '/../../../app/bootstrap.php';
require_once __DIR__ . '/../../../app/Modules/DataExchange/DataExchange.php';
require_once __DIR__ . '/../../../app/Modules/Marketplace/Marketplace.php';
require_once __DIR__ . '/../branches/_helpers.php';
Auth::requireRole(['super_admin', 'owner']);
$db=Database::connect();marketplace_install($db);branch_install($db);$branchId=branch_current_id($db);
$format=strtolower(trim($_GET['format']??'xlsx'));if(!in_array($format,['xlsx','pdf'],true)){http_response_code(400);exit('Format export tidak didukung.');}
$products=$db->query("SELECT p.*,c.name category_name,s.name supplier_name FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN suppliers s ON s.id=p.supplier_id ORDER BY p.name,p.id")->fetchAll();
$records=[];
foreach($products as $p){
    $brand='';$bid=marketplace_v15_product_brand_id($db,(int)$p['id']);if($bid>0){$b=marketplace_v15_brand($db,$bid);$brand=(string)($b['name']??'');}
    $variants=marketplace_v15_variants($db,(int)$p['id'],$branchId,false);
    if($variants){foreach($variants as $v){$vlabel=(string)($v['display_name']??$v['name']);$records[]=['name'=>$p['name'],'brand'=>$brand,'category'=>$p['category_name']??'','variant'=>$vlabel,'variant_sku'=>$v['sku']??'','variant_barcode'=>$v['barcode']??'','product_code'=>$p['product_code']??'','barcode'=>$p['barcode']??'','supplier'=>$p['supplier_name']??'','unit'=>$p['unit']?:'pcs','purchase_price'=>(float)($v['purchase_price']?:$p['purchase_price']),'selling_price'=>(float)($v['selling_price']?:$p['selling_price']),'stock'=>(int)$v['stock'],'minimum_stock'=>(int)($v['minimum_stock']??0),'rack_location'=>$p['rack_location']??'','is_active'=>((int)$p['is_active']===1&&(int)$v['is_active']===1)?'aktif':'nonaktif','description'=>$p['description']??''];}}
    else{$stock=(int)$p['stock'];try{$q=$db->prepare('SELECT stock,minimum_stock FROM product_branch_stocks WHERE branch_id=? AND product_id=? LIMIT 1');$q->execute([$branchId,$p['id']]);if($r=$q->fetch()){$stock=(int)$r['stock'];$p['minimum_stock']=(int)$r['minimum_stock'];}}catch(Throwable $e){}$records[]=['name'=>$p['name'],'brand'=>$brand,'category'=>$p['category_name']??'','variant'=>'','variant_sku'=>'','variant_barcode'=>'','product_code'=>$p['product_code']??'','barcode'=>$p['barcode']??'','supplier'=>$p['supplier_name']??'','unit'=>$p['unit']?:'pcs','purchase_price'=>(float)$p['purchase_price'],'selling_price'=>(float)$p['selling_price'],'stock'=>$stock,'minimum_stock'=>(int)$p['minimum_stock'],'rack_location'=>$p['rack_location']??'','is_active'=>(int)$p['is_active']===1?'aktif':'nonaktif','description'=>$p['description']??''];}
}
$storeName=setting('store_name',setting('app_name','KasirPro UMKM'));$dateStamp=date('Ymd-His');$headers=kp_exchange_product_headers();$labels=kp_exchange_product_label_row();
if($format==='xlsx'){$rows=[[[ 'value'=>'DATA PRODUK POS + BRAND + KATEGORI + VARIAN - '.$storeName,'style'=>1,'height'=>28]],[[ 'value'=>'Diekspor '.date('d/m/Y H:i').' | '.count($records).' baris | File ini dapat diedit lalu di-upload kembali melalui Import Produk','style'=>5]],array_map(fn($h)=>['value'=>$h,'style'=>2],$labels)];foreach($records as $r){$row=[];foreach($headers as $h){$num=in_array($h,['purchase_price','selling_price','stock','minimum_stock'],true);$row[]=['value'=>$r[$h]??'','type'=>$num?'number':'string','style'=>$num?(str_contains($h,'price')?3:4):5];}$rows[]=$row;}Auth::log('export_products','Export data produk/brand/kategori/varian Excel: '.count($records).' baris');KpXlsx::download('data-produk-pos-brand-kategori-varian-'.$dateStamp.'.xlsx',[['name'=>'Data Produk','rows'=>$rows,'widths'=>[32,20,22,22,20,20,20,20,24,10,16,16,10,14,16,12,38],'freeze_rows'=>3,'auto_filter'=>true,'filter_row'=>3,'merges'=>['A1:Q1','A2:Q2']]]);}
$pdfRows=[];$payload=[];foreach($records as $i=>$r){$display=$r['name'].(!empty($r['variant'])?' - '.$r['variant']:'');$payload[]=array_map(fn($h)=>$r[$h]??'',$headers);$pdfRows[]=[['value'=>$i+1,'align'=>'center'],['value'=>$display,'bold'=>true],$r['brand']?:'-',$r['category']?:'-',['value'=>kp_exchange_rupiah_number($r['selling_price']),'align'=>'right'],['value'=>$r['stock'].' '.$r['unit'],'align'=>'right'],$r['is_active']];}
$pdf=new KpPdfDocument('L');$pdf->setTitle('Data Produk & Varian - '.$storeName);$pdf->addPage();$pdf->text(28,30,'DATA PRODUK & VARIAN',18,true);$pdf->text(28,49,$storeName,10,true);$pdf->text(28,65,'Total baris: '.count($records),9);$pdf->line(28,78,$pdf->getWidth()-28,78,.78);$pdf->table(['No','Produk / Varian','Brand','Kategori','Harga','Stok','Status'],$pdfRows,[30,260,90,100,100,80,80],['y'=>90,'font_size'=>7.2,'row_height'=>22,'page_title'=>'Data Produk & Varian - '.$storeName]);$pdf->addEmbeddedComment('PRODUCT-DATA',json_encode(['version'=>3,'source'=>'KasirPro UMKM','headers'=>$headers,'rows'=>$payload],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));Auth::log('export_products','Export produk/varian PDF: '.count($records).' baris');$pdf->download('data-produk-varian-'.$dateStamp.'.pdf');
